function ProgressBar({ onComplete }) {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    const id = setInterval(() => {
      setProgress(p => {
        if (p + 1 >= 100) {
          onComplete();
          return 100;
        }
        return p + 1;
      });
    }, 20);
    return () => clearInterval(id);
  }, []);
  return <div className="fill" style={{ width: progress + '%' }} />;
}
```

