You sketch a minimal query cache in an interview. `staleTime` is 5,000 ms, and `fetchTodos` resolves almost instantly. The calls happen at t = 0, t = 1,000 and t = 7,000 ms. Which statement describes what happens?

```js
const cache = new Map();
function fetchQuery(key, fn, staleTime) {
  const k = JSON.stringify(key);
  const entry = cache.get(k);
  if (entry?.promise) return { data: entry.data, fetching: true };
  if (entry && Date.now() - entry.updatedAt < staleTime) {
    return { data: entry.data, fetching: false };
  }
  const e = entry ?? { data: undefined, updatedAt: 0 };
  e.promise = fn().then(d => {
    e.data = d; e.updatedAt = Date.now(); e.promise = null;
    return d;
  });
  cache.set(k, e);
  return { data: e.data, fetching: true };
}
```

