  if (node.id === parentId) {
    return { ...node, children: [...node.children, newNode] };
  }
  if (!node.children) return node;
  const children = node.children.map(c => addNode(c, parentId, newNode));
  return children.some((c, i) => c !== node.children[i])
    ? { ...node, children }
    : node;
}
```

